      "farmerP2": "రియల్ టైమ్ SMS మరియు యాప్‌లో అప్లికేషన్ ట్రాకింగ్",
      "farmerP3": "భూమికి సంబంధించిన 5-6 ఫోటోలను నేరుగా అప్‌లోడ్ చేయడం",
      "farmerP4": "ధృవీకరణ పూర్తయిన తర్వాత సర్టిఫైడ్ PDF నివేదిక డౌన్‌లోడ్",
