      "tahsildarP1": "కేటాయించిన మండలానికి భౌగోళిక పరిశీలన క్యూ",
      "tahsildarP2": "నేల ఫోటో vs డ్రోన్ ఫోటో ముఖాముఖి పోలిక వేదిక",
      "tahsildarP3": "AI సహాయంతో పంట ప్రకటనల ఖచ్చితమైన ధృవీకరణ",
      "tahsildarP4": "తీసుకున్న నిర్ణయాలపై తప్పనిసరి డిజిటల్ ఆడిట్ రికార్డులు",
      "forFieldWorkers": "ఫీల్డ్ వర్కర్ల కోసం",
      "fieldWorkerP1": "షెడ్యూల్ చేసిన తనిఖీల స్పష్టమైన రోజువారీ జాబితా",
      "fieldWorkerP2": "GPS మిషన్ లాగింగ్ మరియు డ్రోన్ ఫోటో అప్‌లోడ్",
      "fieldWorkerP3": "క్షేత్ర గమనికలు మరియు వ్యత్యాసాల డాక్యుమెంటేషన్",
      "fieldWorkerP4": "మొబైల్‌లో సులభంగా ఫీల్డ్ డేటా సేకరణ",
      "forAdmins": "నిర్వాహకుల కోసం",
