    faqSection: {
      "badge": "సాధారణ ప్రశ్నలు",
      "title": "తరచుగా అడిగే ప్రశ్నలు",
      "q1": "రైతులు అగ్రిసర్వేలో వ్యవసాయ భూమిని ఎలా నమోదు చేసుకోవచ్చు?",
      "a1": "రైతులు ఉచిత ఖాతా సృష్టించి, సంప్రదింపు వివరాలు, 7/12 లేదా పట్టా నంబర్, సర్వే నంబర్, విస్తీర్ణం నమోదు చేసి 4 దశల్లో దరఖాస్తు చేయవచ్చు.",
      "q2": "రైతులు 5 నుండి 6 క్షేత్ర ఫోటోలను ఎందుకు అప్‌లోడ్ చేయాలి?",
      "a2": "తహశీల్దార్ ప్రాథమిక ఆమోదం తర్వాత, డ్రోన్ సర్వేకు ముందు సరిహద్దులు, పంట సాళ్లు మరియు సాగునీటి వనరుల స్పష్టమైన ఆధారాల కోసం ఈ ఫోటోలు అవసరం.",
      "q3": "డ్రోన్ ఆధారిత వైమానిక తనిఖీ ఎలా పనిచేస్తుంది?",
      "a3": "అధీకృత ఫీల్డ్ వర్కర్ భూమిని సందర్శించి, RTK డ్రోన్ ద్వారా 45 మీటర్ల ఎత్తు నుండి స్పష్టమైన చిత్రాలను తీసి రెవెన్యూ అధికారికి సమర్పిస్తారు.",
      "q4": "అగ్రిసర్వే ధృవీకరణ చట్టపరమైన భూ యాజమాన్యాన్ని నిర్ధారిస్తుందా?",
      "a4": "లేదు. అగ్రిసర్వే అనేది డ్రోన్ చిత్రాలు మరియు ప్రత్యక్ష వాస్తవాలను సరిపోల్చే సాంకేతిక ధృవీకరణ వేదిక. ఇది కోర్టు తీర్పులకు ప్రత్యామ్నాయం కాదు.",
      "q5": "తహశీల్దార్ దరఖాస్తులను ఎలా సమీక్షించి నిర్ణయం తీసుకుంటారు?",
      "a5": "తహశీల్దార్లు తమ అధికారిక పోర్టల్ ద్వారా దరఖాస్తులను పరిశీలించి ఆమోదించడం, కారణాలతో తిరస్కరించడం, వివరణ కోరడం మరియు తుది నివేదికలు జారీ చేయడం చేస్తారు."
    },
