    faqSection: {
      "badge": "ಸಾಮಾನ್ಯ ಪ್ರಶ್ನೆಗಳು",
      "title": "ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು",
      "q1": "ರೈತರು ಅಗ್ರಿಸರ್ವೇಯಲ್ಲಿ ಕೃಷಿ ಜಮೀನನ್ನು ಹೇಗೆ ನೋಂದಾಯಿಸಬಹುದು?",
      "a1": "ರೈತರು ಉಚಿತ ಖಾತೆ ರಚಿಸಿ, ಸಂಪರ್ಕ ವಿವರಗಳು, 7/12 ಅಥವಾ ಪಹಣಿ ಸಂಖ್ಯೆ, ಸರ್ವೆ ಸಂಖ್ಯೆ, ವಿಸ್ತೀರ್ಣ ನಮೂದಿಸಿ 4 ಹಂತಗಳಲ್ಲಿ ಅರ್ಜಿ ಸಲ್ಲಿಸಬಹುದು.",
      "q2": "ರೈತರು 5 ರಿಂದ 6 ಜಮೀನಿನ ಛಾಯಾಚಿತ್ರಗಳನ್ನು ಏಕೆ ಅಪ್‌ಲೋಡ್ ಮಾಡಬೇಕು?",
      "a2": "ತಹಶೀಲ್ದಾರ್ ಪ್ರಾಥಮಿಕ ಅನುಮೋದನೆ ನೀಡಿದ ನಂತರ, ಡ್ರೋನ್ ಸಮೀಕ್ಷೆಗೆ ಮುಂಚಿತವಾಗಿ ಗಡಿಗಳು, ಬೆಳೆ ಸಾಲುಗಳು ಮತ್ತು ನೀರಾವರಿ ಸೌಲಭ್ಯಗಳ ಸ್ಪಷ್ಟ ಪುರಾವೆಗಾಗಿ ಈ ಫೋಟೋಗಳು ಅಗತ್ಯ.",
      "q3": "ಡ್ರೋನ್ ಆಧಾರಿತ ವೈಮಾನಿಕ ತಪಾಸಣೆ ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ?",
      "a3": "ಅಧಿಕೃತ ಕ್ಷೇತ್ರ ಕಾರ್ಯಕರ್ತರು ಜಮೀನಿಗೆ ಭೇಟಿ ನೀಡಿ, RTK ಡ್ರೋನ್ ಮೂಲಕ 45 ಮೀಟರ್ ಎತ್ತರದಿಂದ ಹೈ-ರೆಸಲ್ಯೂಶನ್ ಚಿತ್ರಗಳನ್ನು ಸೆರೆಹಿಡಿದು ಕಂದಾಯ ಅಧಿಕಾರಿಗೆ ಸಲ್ಲಿಸುತ್ತಾರೆ.",
      "q4": "ಅಗ್ರಿಸರ್ವೇ ಪರಿಶೀಲನೆಯು ಕಾನೂನುಬದ್ಧ ಜಮೀನು ಮಾಲೀಕತ್ವವನ್ನು ಪ್ರಮಾಣೀಕರಿಸುತ್ತದೆಯೇ?",
      "a4": "ಇಲ್ಲ. ಅಗ್ರಿಸರ್ವೇ ಎಂಬುದು ಡ್ರೋನ್ ಚಿತ್ರಗಳು ಮತ್ತು ನೆಲದ ವಾಸ್ತವತೆಯನ್ನು ಹೋಲಿಸುವ ತಾಂತ್ರಿಕ ಪರಿಶೀಲನಾ ವೇದಿಕೆಯಾಗಿದೆ. ಇದು ನ್ಯಾಯಾಲಯದ ತೀರ್ಪುಗಳಿಗೆ ಪರ್ಯಾಯವಲ್ಲ.",
      "q5": "ತಹಶೀಲ್ದಾರರು ಅರ್ಜಿಗಳನ್ನು ಹೇಗೆ ಪರಿಶೀಲಿಸಿ ನಿರ್ಧಾರ ತೆಗೆದುಕೊಳ್ಳುತ್ತಾರೆ?",
      "a5": "ತಹಶೀಲ್ದಾರರು ತಮ್ಮ ಅಧಿಕೃತ ಪೋರ್ಟಲ್ ಮೂಲಕ ಅರ್ಜಿಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಅನುಮೋದಿಸಲು, ಕಾರಣಗಳೊಂದಿಗೆ ತಿರಸ್ಕರಿಸಲು, ಸ್ಪಷ್ಟನೆ ಕೇಳಲು ಮತ್ತು ಅಂತಿಮ ವರದಿಗಳನ್ನು ನೀಡಲು ಸಾಧ್ಯವಾಗುತ್ತದೆ."
    },
