      "q1": "ખેડૂતો એગ્રીસર્વે પર ખેતજમીનની નોંધણી કેવી રીતે કરી શકે?",
      "a1": "ખેડૂતો મફત ખાતું બનાવીને, સંપર્ક માહિતી, 7/12 નંબર, સર્વે નંબર, ક્ષેત્રફળ દાખલ કરી 4 તબક્કામાં અરજી સબમિટ કરી શકે છે.",
