      "q3": "ડ્રોન આધારિત હવાઈ તપાસ કેવી રીતે કાર્ય કરે છે?",
      "a3": "અધિકૃત ફિલ્ડ વર્કર જમીનની મુલાકાત લઈને, RTK ડ્રોન દ્વારા 45 મીટરની ઊંચાઈએથી હાઇ-રિઝોલ્યુશન તસવીરો લઈને મહેસૂલ અધિકારીને મોકલે છે.",
      "q4": "શું એગ્રીસર્વે ચકાસણી કાનૂની માલિકી હક પ્રમાણિત કરે છે?",
      "a4": "ના. એગ્રીસર્વે એ ડ્રોન ઇમેજ અને જમીનની વાસ્તવિકતા વચ્ચેની તકનીકી પુરાવા-આધારિત સરખામણી છે. તે કોર્ટના નિર્ણયોનું સ્થાન લેતું નથી.",
