      "q1": "ਕਿਸਾਨ ਐਗਰੀਸਰਵੇ 'ਤੇ ਖੇਤੀਬਾੜੀ ਜ਼ਮੀਨ ਕਿਵੇਂ ਰਜਿਸਟਰ ਕਰ ਸਕਦੇ ਹਨ?",
      "a1": "ਕਿਸਾਨ ਮੁਫ਼ਤ ਖਾਤਾ ਬਣਾ ਕੇ, ਸੰਪਰਕ ਵੇਰਵੇ, ਜ਼ਮੀਨੀ ਰਿਕਾਰਡ ਨੰਬਰ, ਖਸਰਾ ਨੰਬਰ, ਰਕਬਾ ਦਰਜ ਕਰਕੇ 4 ਪੜਾਵਾਂ ਵਿੱਚ ਅਰਜ਼ੀ ਦੇ ਸਕਦੇ ਹਨ।",
      "q2": "ਕਿਸਾਨਾਂ ਨੂੰ 5 ਤੋਂ 6 ਜ਼ਮੀਨੀ ਤਸਵੀਰਾਂ ਅੱਪਲੋਡ ਕਰਨ ਦੀ ਲੋੜ ਕਿਉਂ ਹੈ?",
