      "q3": "ਡਰੋਨ ਅਧਾਰਿਤ ਹਵਾਈ ਨਿਰੀਖਣ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ?",
      "a3": "ਅਧਿਕਾਰਤ ਫੀਲਡ ਵਰਕਰ ਜ਼ਮੀਨ ਦਾ ਦੌਰਾ ਕਰਕੇ, RTK ਡਰੋਨ ਰਾਹੀਂ 45 ਮੀਟਰ ਦੀ ਉਚਾਈ ਤੋਂ ਉੱਚ-ਰੈਜ਼ੋਲਿਊਸ਼ਨ ਤਸਵੀਰਾਂ ਲੈ ਕੇ ਮਾਲ ਅਧਿਕਾਰੀ ਨੂੰ ਭੇਜਦਾ ਹੈ।",
      "q4": "ਕੀ ਐਗਰੀਸਰਵੇ ਪੜਤਾਲ ਕਾਨੂੰਨੀ ਮਾਲਕੀ ਹੱਕ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੀ ਹੈ?",
      "a4": "ਨਹੀਂ। ਐਗਰੀਸਰਵੇ ਡਰੋਨ ਤਸਵੀਰਾਂ ਅਤੇ ਜ਼ਮੀਨੀ ਹਕੀਕਤ ਵਿਚਕਾਰ ਇੱਕ ਤਕਨੀਕੀ ਸਬੂਤ-ਅਧਾਰਿਤ ਪੜਤਾਲ ਪਲੇਟਫਾਰਮ ਹੈ। ਇਹ ਅਦਾਲਤੀ ਫੈਸਲਿਆਂ ਦਾ ਬਦਲ ਨਹੀਂ ਹੈ।",
      "q5": "ਤਹਿਸੀਲਦਾਰ ਅਰਜ਼ੀਆਂ ਦੀ ਸਮੀਖਿਆ ਅਤੇ ਫੈਸਲਾ ਕਿਵੇਂ ਲੈਂਦੇ ਹਨ?",
      "a5": "ਤਹਿਸੀਲਦਾਰ ਆਪਣੇ ਅਧਿਕਾਰ ਖੇਤਰ ਦੇ ਪੋਰਟਲ ਰਾਹੀਂ ਅਰਜ਼ੀਆਂ ਦੀ ਜਾਂਚ ਕਰਕੇ ਮਨਜ਼ੂਰੀ, ਕਾਰਨਾਂ ਸਮੇਤ ਅਸਵੀਕਾਰ, ਸਪੱਸ਼ਟੀਕਰਨ ਮੰਗਣਾ ਅਤੇ ਅੰਤਿਮ ਰਿਪੋਰਟ ਜਾਰੀ ਕਰਦੇ ਹਨ।"
