      "q1": "കർഷകർക്ക് അഗ്രിസർവേയിൽ കൃഷിഭൂമി എങ്ങനെ രജിസ്റ്റർ ചെയ്യാം?",
      "a1": "കർഷകർക്ക് സൗജന്യ അക്കൗണ്ട് സൃഷ്ടിച്ച്, ബന്ധപ്പെടാനുള്ള വിവരങ്ങൾ, 7/12 അല്ലെങ്കിൽ പട്ടയം നമ്പർ, സർവേ നമ്പർ, വിസ്തീർണ്ണം നൽകി 4 ഘട്ടങ്ങളിലായി അപേക്ഷിക്കാം.",
      "q2": "കർഷകർ 5 മുതൽ 6 വരെ ഫീൽഡ് ഫോട്ടോകൾ അപ്‌ലോഡ് ചെയ്യേണ്ടത് എന്തുകൊണ്ട്?",
      "a2": "തഹസിൽദാറുടെ പ്രാഥമിക അനുമതിക്ക് ശേഷം, ഡ്രോൺ സർവേയ്ക്ക് മുമ്പ് അതിരുകൾ, വിള നിരകൾ, ജലസേചന സൗകര്യങ്ങൾ എന്നിവയുടെ വ്യക്തമായ തെളിവിനായി ഈ ഫോട്ടോകൾ ആവശ്യമാണ്.",
      "q3": "ഡ്രോൺ അധിഷ്ഠിത വ്യോമ പരിശോധന എങ്ങനെ പ്രവർത്തിക്കുന്നു?",
      "a3": "അധികാരപ്പെടുത്തിയ ഫീൽഡ് വർക്കർ ഭൂമി സന്ദർശിച്ച്, RTK ഡ്രോൺ വഴി 45 മീറ്റർ ഉയരത്തിൽ നിന്ന് വ്യക്തമായ ചിത്രങ്ങൾ എടുത്ത് റവന്യൂ ഉദ്യോഗസ്ഥന് സമർപ്പിക്കുന്നു.",
      "q4": "അഗ്രിസർവേ പരിശോധന നിയമപരമായ ഭൂവുടമസ്ഥാവകാശം സാക്ഷ്യപ്പെടുത്തുന്നുണ്ടോ?",
      "a4": "ഇല്ല. അഗ്രിസർവേ എന്നത് ഡ്രോൺ ചിത്രങ്ങളും ഭൂമിയിലെ യാഥാർത്ഥ്യവും തമ്മിലുള്ള സാങ്കേതിക തെളിവ് അധിഷ്ഠിത പരിശോധനാ പ്ലാറ്റ്‌ഫോമാണ്. ഇത് കോടതി വിധികളുടെ പകരമല്ല.",
      "q5": "തഹസിൽദാർ അപേക്ഷകൾ എങ്ങനെ അവലോകനം ചെയ്യുകയും തീരുമാനമെടുക്കുകയും ചെയ്യുന്നു?",
      "a5": "തഹസിൽദാർമാർ അവരുടെ ഔദ്യോഗിക പോർട്ടൽ വഴി അപേക്ഷകൾ പരിശോധിച്ച് അംഗീകരിക്കുകയോ, കാരണങ്ങളോടെ നിരസിക്കുകയോ, വിശദീകരണം തേടുകയോ, അന്തിਮ റിപ്പോർട്ട് നൽകുകയോ ചെയ്യുന്നു."
